-- Возврат к прежнему сантехническому шаблону из baseline: 100 позиций -> 58.
--
-- Откат восстанавливает ровно те строки, что стояли в 000001, включая ключи 20-й размерности. Цены,
-- проставленные владельцами под новыми ключами, эта миграция вернуть не может - они живут в
-- `products` и умрут при следующем «Применить ко всем», когда синхронизация уберёт из магазинов
-- строки с ключами, которых больше нет в шаблоне.

DELETE FROM product_templates WHERE shop_category = 'plumbing';

